import { MeshBasicNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu';
import { uv, vec3, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Vector3, DirectionalLight } = ctx.THREE;
  const mainGroup = new Group();

  // Create Backdrop & Stage to avoid FLAT_VOID
  const backdropGeo = new PlaneGeometry(8, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const gradUv = uv();
  const backdropColor = gradUv.y.mix(vec3(0.04, 0.04, 0.06), vec3(0.08, 0.08, 0.12));
  backdropMat.colorNode = backdropColor;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.6);
  mainGroup.add(backdrop);

  // Accent local lighting
  const rimLight = new DirectionalLight('#ff2a38', 1.2);
  rimLight.position.set(-3, 3, 2);
  mainGroup.add(rimLight);

  // Load Textures
  const uTexture = uniform(null);
  const uDepth = uniform(null);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = 'srgb';
      uTexture.value = tex;
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      uDepth.value = tex;
    });
  }

  // Create displaced/parallax plane
  const geometry = new PlaneGeometry(4.5, 3.2, 128, 128);
  const material = new MeshBasicNodeMaterial();

  const texCoord = uv();
  const depthVal = texture(uDepth, texCoord).r;
  const displacedPos = vec3(0, 0, depthVal.mul(0.4));
  material.positionNode = displacedPos;

  const colorVal = texture(uTexture, texCoord);
  material.colorNode = colorVal;

  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, 0.2, 0.1);
  mainGroup.add(mesh);

  // Inner container for handling internal hover logic
  const interactiveGroup = new Group();
  interactiveGroup.add(mesh);
  mainGroup.add(interactiveGroup);

  // Render static fallback text to ensure typography is present (as per ATLAS REGION and spec elements)
  const quoteText = ctx.fontAtlas.createText('"PRECISION IS THE SIGNATURE OF TIME"', {
    fontSize: 0.16,
    color: '#e8ecf2',
    align: 'center'
  });
  quoteText.position.set(0, -1.0, 0.4);
  interactiveGroup.add(quoteText);

  const authorText = ctx.fontAtlas.createText('ATELIER NOVELTY CO.', {
    fontSize: 0.1,
    color: '#ff2a38',
    align: 'center'
  });
  authorText.position.set(0, -1.3, 0.45);
  interactiveGroup.add(authorText);

  // Contact shadow
  const shadowGeo = new PlaneGeometry(4.8, 0.6);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacity = 0.45;
  shadowMat.transparent = true;
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -1.5, -0.1);
  shadow.rotation.x = -Math.PI * 0.4;
  mainGroup.add(shadow);

  // Initial Settle Entrance
  gsap.fromTo(
    interactiveGroup.position,
    { y: -0.3, z: -0.5 },
    { y: 0, z: 0, duration: 0.9, ease: 'power4.out' }
  );

  // Apply Cinematic Primitives
  const primitiveInstances = [];
  if (config.cinematicPrimitives) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives[primitive.name]) {
        const inst = ctx.primitives[primitive.name](mesh, primitive.params);
        if (inst) primitiveInstances.push(inst);
      }
    }
  }

  // Interactivity Handlers
  let isHovered = false;
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(interactiveGroup.position, { y: 0.15, duration: 0.35, ease: 'power2.out' });

  mesh.userData.handlers = {
    onPointerOver: () => {
      if (!isHovered) {
        isHovered = true;
        hoverTl.play();
      }
    },
    onPointerOut: () => {
      if (isHovered) {
        isHovered = false;
        hoverTl.reverse();
      }
    },
    onClick: () => {
      gsap.fromTo(
        interactiveGroup.scale,
        { x: 0.96, y: 0.96, z: 0.96 },
        { x: 1, y: 1, z: 1, duration: 0.25, ease: 'back.out(2)' }
      );
      ctx.emit('hub-home.select', { id: config.id });
    }
  };

  // Cleanup Function
  mainGroup.userData.cleanup = () => {
    hoverTl.kill();
    primitiveInstances.forEach((inst) => {
      if (inst.cleanup) inst.cleanup();
      if (inst.timeline) inst.timeline.kill();
    });
    geometry.dispose();
    material.dispose();
    backdropGeo.dispose();
    backdropMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
  };

  return mainGroup;
}
